SELECT id, supplier_name, country, city, rating, SUM(rating) OVER (PARTITION BY country) AS country_sum_rating, LEAD(rating, 2) OVER (PARTITION BY country ORDER BY rating, id) AS next_rating, NTILE(5) OVER (PARTITION BY city ORDER BY rating, id) AS rating_bucket, ROW_NUMBER() OVER (ORDER BY rating, id) AS row_seq, LEAD(rating, 1) OVER (ORDER BY rating, id) AS next_rating_2 FROM suppliers
